                        zzb_yase: ['male', 'zzb_rong', 3, ['ys_sg', 'ys_sj', 'ys_sd', 'ys_sp', 'ys_ys'], ['des:长久以来,崇尚英勇,荣耀与美德的圣骑士们守护着勇士之地.他们每年秋季都会举行武道大会,并演变为一大盛事.人们白天比武,夜晚饮酒作乐,欢庆丰收.最后的胜利者将加入圣骑士团,成为其中的一员. 然而,随着帝国与同盟的战争常年不熄,英勇的圣骑士相继牺牲,圣骑士团的力量逐渐衰落,进而陷入争吵和分裂.这件事被敌对者所利用,策划着要将圣骑士们一举抹杀. 这一年的武道大会如期举行,人们从四面八方涌向勇士之地.此时同盟的军队发动了突袭.他们如暴风般席卷了防卫空虚的城镇和村庄,又像闪电一样离开,当圣骑士团赶到时,只留下焚烧后的废墟与悲泣的人们. 这样的惨剧在短短数天内反复上演了三次.勇士之地陷入了恐慌中.圣骑士团疲于奔命却无能为力.紧接着,更加大胆的第四次袭击,直指圣骑士团的所在之地.如果让他们得逞,圣骑士团数百年来的荣耀会彻底的丧失. 骑士们星夜奔回时,却看到与预想完全不同的景象:神圣的殿堂依然庄严高耸,鲜血和头颅都来自卑鄙的袭击者.独自一人完成这丰功伟绩的,是位远道而来的青年旅人.而他手中竟然持着被称为<王者之剑>的誓约胜利之剑.这把剑原本插在圣堂供奉的巨石中,据说是由湖中仙女敬献给远古最伟大的亚瑟王. 得救的人们讲述了当时的情景:袭击者们冲入圣地,人们四散逃窜.旅人原本的铁剑在砍杀中折断.他看到了巨石中的圣剑,轻松拔出它,并击退所有敌人. 圣骑士团轰动了.拔出誓约胜利之剑的人将获得圣骑士们的效忠,这古老的条约代代相传.他们将拯救了圣地的青年围在中间,举剑向他宣誓忠诚! 亚瑟率领下,圣骑士团开始伟大的复兴.在他们的支持下,亚瑟集合了勇士之地的力量,将创造新的理想乡作为自己的信仰.这位王者将他的剑指向了过去的袭击者们.这些强盗将为血的回忆付出代价. <永不背叛!>~亚瑟']],
