                        zzb_caiyuemao: ['male', 'zzb_ling', 5, ['cym_sw', 'cym_hg', 'cym_pt', 'cym_mao'], ['des:菜月昴(486)是轻小说<Re:从零开始的异世界生活>[1]及其衍生作品中的主人公.为人正直善良,有着在逆境中边叫苦边抵抗的品格.穿着与异世界格格不入的运动服.经常锻炼,有着良好的体格,从现代日本的便利店买完泡面就莫名其妙穿越到异世界.  被<嫉妒魔女>莎缇拉深爱,拥有权能<死亡回归>.喜欢爱蜜莉雅,深信她是自己在异世界的女主角,为了守护爱蜜莉雅的笑容和走向理想的Happy Ending而不断在死亡中轮回.  自我定位为<爱蜜莉雅的骑士>,被雷姆定义自己的<英雄>,将上述两人称为<心中不可撼动的第一位和第二位>.被魔女教徒们称为<贤者的候补>,与加菲尔·汀泽尔并称<守护爱蜜莉雅的双壁']],
                        zzb_dongfangyuechu: ['male', 'zzb_yao', 4, ['dfyc_yy', 'dfyc_xk', 'dfyc_dzxy'], ['des:东方月初,中国漫画<狐妖小红娘>及其衍生作品中的主要人物之一.  一气道盟中有名的后起之秀,后晋升盟主,成为道界最强之人.能力超群,能使用狐族法术.幼年时曾被涂山红红救下,一直称红红为妖仙姐姐.原本打算在七夕向她表白却未能如愿,想要实现涂山红红的某个梦想']],
                        zzb_mingren: ['male', 'zzb_ren', 4, ['mr_lxw', 'mr_sy', 'mr_xm', 'mr_fs', 'mr_hg'], ['des: 目录 木叶村第七代火影漩涡鸣人 146.6万 57" 一分钟了解漩涡鸣人 78.1万 50" <火影忍者>从开篇到博人传:不同时期的漩涡鸣人! 43.2万 3\'44" 鸣人五次流泪瞬间,分别代表亲情,友情,师徒之情,唯独没有爱情 20.2万 2\'25" 鸣人被这位大姐揍扁了,偏偏大姐还把他忘了,鸣人气得直冒烟 16万 1\'29" >     漩涡鸣人 日本漫画<火影忍者>系列男主角 本词条是多义词,共2个义项 展开 特色词条 | 本词条按照特色词条指南编辑并维护 贡献维护者 tst505、安迪布兰顿大人  漩涡鸣人,日本漫画<火影忍者>及其衍生作品中的男主角.火之国木叶隐村的忍者,第四代火影波风水门和漩涡玖辛奈之子,六道仙人次子阿修罗的查克拉转世者.刚出生时父母为保护村子而牺牲,并将尾兽<九尾>封印在鸣人体内.成为孤儿的鸣人从小被村民歧视,但在唯一认同他的老师海野伊鲁卡以及第三代火影猿飞日斩的鼓励下有了要成为火影的梦想,让所有人都认同他的存在.成为忍者后,和旗木卡卡西、宇智波佐助以及春野樱组成第七班进行各种任务.  为实现梦想,和守护伙伴们的羁绊,鸣人不断修炼变强,作为木叶<三忍>之一自来也的弟子,在追求梦想的过程中不断突破自我,贯彻了自身的忍道,获得人们的认可.最后与忍者联军以及宇智波佐助还有九尾一同终结了战争,为忍者世界带来和平,并实现自己成为火影(第七代火影)和忍界英雄的梦想']],
